import { Metadata } from "next";
import { prisma } from "@/lib/prisma";
import PartnerCarousel from "@/components/PartnerCarousel";

export const metadata: Metadata = {
    title: "100 Жилийн Ой — Зууны Нөлөөлөл | МҮЗХ",
    description: "Монголын Үндэсний Зуслангуудын Холбооны 100 жилийн түүхэн замнал (1926-2026)",
};

export const dynamic = "force-dynamic";

const defaultTimeline = [
    {
        year: "1926",
        title: "Үүсгэн байгуулагдсан",
        description: "Монголын Залуучуудын Зөвлөл байгуулагдаж, залуу хойч үеийнхээ төлөө дуу хоолойгоо нэгтгэсэн.",
        imageUrl: "https://images.unsplash.com/photo-1461360228754-6e81c478b882?w=600&q=80",
    },
    {
        year: "1950-аад",
        title: "Аж үйлдвэржилт ба Хөгжил",
        description: "МҮЗХ-ын гишүүд дэд бүтцийн төслүүдийг хэрэгжүүлж, орон нутгийн хөгжилд хувь нэмрээ оруулсан.",
        imageUrl: "https://images.unsplash.com/photo-1529156069898-49953e39b3ac?w=600&q=80",
    },
    {
        year: "1990-ээд",
        title: "Ардчилал ба Дижитал Эхлэл",
        description: "МҮЗХ Монголын ардчилсан шилжилтэд чухал үүрэг гүйцэтгэж, технологийн нэвтрүүлэлтийг дэмжсэн.",
        imageUrl: "https://images.unsplash.com/photo-1522202176988-66273c2fd55f?w=600&q=80",
    },
    {
        year: "2026",
        title: "Шинэ Бүлэг",
        description: "100 жилийн ойгоо тэмдэглэн, дижитал шинэчлэл болон дэлхийн холбоо барилцааны ирээдүйг угтаж байна.",
        imageUrl: "https://images.unsplash.com/photo-1531482615713-2afd69097998?w=600&q=80",
    },
];

export default async function AnniversaryPage() {
    const dbSettings = await prisma.siteSetting.findMany({
        where: {
            key: {
                in: [
                    'anniversary_video_url',
                    'anniversary_hero_badge',
                    'anniversary_hero_title',
                    'anniversary_hero_text',
                    'anniversary_logo_url',
                    'anniversary_intro_title',
                    'anniversary_intro_text',
                    'anniversary_accordions',
                    'anniversary_timeline',
                ]
            }
        }
    });

    const sm = dbSettings.reduce((acc, curr) => {
        acc[curr.key] = curr.value;
        return acc;
    }, {} as Record<string, string>);

    const videoUrl = sm['anniversary_video_url'] || "https://www.youtube.com/embed/A6XUVjK9W4o";
    const heroTitle = sm['anniversary_hero_title'] || "Зууны Нөлөөлөл (1926–2026)";
    const heroText = sm['anniversary_hero_text'] || "100 жилийн түүхэн уламжлал ба дижитал шинэчлэлийн аялалыг судлах";

    let timeline = defaultTimeline;
    try {
        const parsed = JSON.parse(sm['anniversary_timeline'] || "[]");
        if (parsed && parsed.length > 0) timeline = parsed;
    } catch (e) {}

    // Research posts
    const researchPosts = await prisma.post.findMany({
        where: { type: "RESEARCH", published: true },
        orderBy: { createdAt: "desc" },
    });

    // Accordions
    let accordions: any[] = [];
    try {
        accordions = JSON.parse(sm['anniversary_accordions'] || "[]");
    } catch (e) {}

    return (
        <div className="min-h-screen bg-[#0F1B3D] text-white">
            {/* ===== HERO ===== */}
            <section className="relative py-20 md:py-32 overflow-hidden">
                {/* BG blobs */}
                <div className="absolute top-0 right-0 w-[600px] h-[600px] bg-[#1A2B5C] rounded-full opacity-50 blur-[150px] -mr-48 -mt-48" />
                <div className="absolute bottom-0 left-0 w-[400px] h-[400px] bg-[#D4A843] rounded-full opacity-10 blur-[120px] -ml-24 -mb-24" />

                <div className="container mx-auto px-4 md:px-6 relative z-10">
                    <div className="max-w-4xl mx-auto text-center space-y-8">
                        <div className="inline-flex items-center rounded-full bg-white/10 border border-white/10 px-5 py-2 backdrop-blur-sm">
                            <span className="text-sm font-bold text-[#F5C542] uppercase tracking-widest">Түүхэн замнал</span>
                        </div>
                        <h1 className="text-4xl md:text-6xl lg:text-7xl font-black tracking-tight leading-tight">
                            МҮЗХ: <span className="text-[#F5C542]">{heroTitle}</span>
                        </h1>
                        <p className="text-xl md:text-2xl text-white/60 font-medium max-w-2xl mx-auto">
                            {heroText}
                        </p>
                    </div>
                </div>
            </section>

            {/* ===== TIMELINE ===== */}
            <section className="py-16 md:py-24 relative">
                <div className="container mx-auto px-4 md:px-6 max-w-6xl">
                    <div className="relative">
                        {/* Golden timeline line */}
                        <div className="timeline-line" />

                        <div className="space-y-20 md:space-y-32">
                            {timeline.map((event: any, i: number) => (
                                <div key={i} className="relative">
                                    {/* Timeline dot */}
                                    <div className="timeline-dot" />

                                    {/* Content card */}
                                    <div className={`ml-16 md:ml-0 md:w-[45%] ${i % 2 === 0 ? 'md:mr-auto md:pr-12' : 'md:ml-auto md:pl-12'}`}>
                                        {/* Year badge */}
                                        <div className="inline-flex items-center bg-[#D4A843] text-[#0F1B3D] font-black text-xl px-5 py-2 rounded-xl mb-6 shadow-lg shadow-yellow-500/20">
                                            {event.year}
                                        </div>

                                        <h3 className="text-2xl md:text-3xl font-black text-white mb-4 leading-tight">
                                            {event.year} — {event.title}
                                        </h3>

                                        {/* Image card */}
                                        {event.imageUrl && (
                                            <div className="relative rounded-2xl overflow-hidden mb-6 group">
                                                <div className="aspect-video bg-[#1A2B5C]">
                                                    <img
                                                        src={event.imageUrl}
                                                        alt={event.title}
                                                        className="w-full h-full object-cover opacity-80 group-hover:opacity-100 group-hover:scale-105 transition-all duration-500"
                                                    />
                                                </div>
                                                {/* Play button overlay for video items */}
                                                {event.videoUrl && (
                                                    <div className="absolute inset-0 flex items-center justify-center">
                                                        <div className="play-button">
                                                            <svg viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z"/></svg>
                                                        </div>
                                                    </div>
                                                )}
                                                {/* Bottom gradient with description */}
                                                <div className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-[#0F1B3D]/90 via-[#0F1B3D]/40 to-transparent p-6">
                                                    <p className="text-white/80 text-sm font-medium">{event.description}</p>
                                                </div>
                                            </div>
                                        )}

                                        {!event.imageUrl && (
                                            <div className="glass-card rounded-2xl p-6 mb-6">
                                                <p className="text-white/70 font-medium leading-relaxed">{event.description}</p>
                                            </div>
                                        )}
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            </section>

            {/* ===== VIDEO SECTION ===== */}
            <section className="py-16 md:py-24">
                <div className="container mx-auto px-4 md:px-6 max-w-5xl">
                    <div className="text-center mb-12">
                        <h2 className="text-3xl md:text-4xl font-black text-white mb-4">Танилцуулга видео</h2>
                        <p className="text-white/50 text-lg">100 жилийн ойн тусгай баримтат кино</p>
                    </div>
                    <div className="rounded-2xl overflow-hidden shadow-2xl shadow-black/30 border border-white/10 bg-black aspect-video">
                        <iframe
                            className="w-full h-full"
                            src={videoUrl}
                            title="100 Жилийн Ойн Танилцуулга"
                            frameBorder="0"
                            allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
                            allowFullScreen
                        />
                    </div>
                </div>
            </section>

            {/* ===== PROGRAMS ACCORDION ===== */}
            {accordions.length > 0 && (
                <section className="py-16 md:py-24 bg-[#1A2B5C]/30">
                    <div className="container mx-auto px-4 md:px-6 max-w-4xl">
                        <div className="text-center mb-12">
                            <h2 className="text-3xl md:text-4xl font-black text-white mb-4">Үйл ажиллагаа ба Хөтөлбөрүүд</h2>
                            <p className="text-white/50 text-lg">Ойн баярын хүрээнд зохион байгуулагдах хөтөлбөрүүд</p>
                        </div>
                        <div className="space-y-4">
                            {accordions.map((acc: any, index: number) => (
                                <details key={index} className="group glass-card rounded-xl overflow-hidden [&_summary::-webkit-details-marker]:hidden">
                                    <summary className="flex cursor-pointer items-center justify-between p-6 hover:bg-white/5 transition-colors">
                                        <span className="text-lg font-bold text-white">{acc.title || "Гарчиггүй"}</span>
                                        <span className="transition duration-300 group-open:-rotate-180 bg-white/10 p-2 rounded-full text-white/50">
                                            <svg fill="none" height="20" stroke="currentColor" strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" viewBox="0 0 24 24" width="20"><path d="M6 9l6 6 6-6"/></svg>
                                        </span>
                                    </summary>
                                    <div className="px-6 pb-6 pt-2 text-white/60 border-t border-white/10">
                                        <p className="whitespace-pre-wrap leading-relaxed">{acc.content || "Дэлгэрэнгүй мэдээлэл оруулаагүй байна."}</p>
                                    </div>
                                </details>
                            ))}
                        </div>
                    </div>
                </section>
            )}

            {/* ===== RESEARCH POSTS ===== */}
            {researchPosts.length > 0 && (
                <section className="py-16 md:py-24">
                    <div className="container mx-auto px-4 md:px-6 max-w-6xl">
                        <div className="text-center mb-12">
                            <div className="inline-flex items-center gap-2 bg-white/10 text-[#F5C542] px-4 py-1.5 rounded-full text-sm font-bold mb-4 border border-white/10">
                                🔬 Эрдэм шинжилгээ
                            </div>
                            <h2 className="text-3xl md:text-4xl font-black text-white">Судалгаа, Өгүүллүүд</h2>
                        </div>
                        <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-8">
                            {researchPosts.map((post: any) => (
                                <a key={post.id} href={`/news/${post.slug}`} className="group glass-card rounded-2xl overflow-hidden hover:border-[#D4A843]/30 transition-all duration-300 hover:-translate-y-1">
                                    {post.imageUrl && (
                                        <div className="aspect-video bg-[#1A2B5C] overflow-hidden">
                                            <img src={post.imageUrl} alt={post.title} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500 opacity-80 group-hover:opacity-100" />
                                        </div>
                                    )}
                                    <div className="p-6">
                                        <h3 className="text-lg font-bold text-white group-hover:text-[#F5C542] transition-colors mb-2 line-clamp-2">{post.title}</h3>
                                        {post.excerpt && <p className="text-sm text-white/50 line-clamp-3">{post.excerpt}</p>}
                                        <div className="mt-4 text-xs text-white/30">{new Date(post.createdAt).toLocaleDateString()}</div>
                                    </div>
                                </a>
                            ))}
                        </div>
                    </div>
                </section>
            )}

            {/* ===== PARTNERS ===== */}
            <section className="bg-white py-16 rounded-t-[3rem]">
                <PartnerCarousel />
            </section>
        </div>
    );
}
